contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint256 burnAmount) public payable {
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 before = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 afterBal = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        assert(reverted || (before >= burnAmount && afterBal == before - burnAmount));
    }
}

