pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount) internal {
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint256 before;
        try c.balanceOf(owner) returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }
        uint256 afterBal;
        try c.balanceOf(owner) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(reverted || (before >= burnAmount && afterBal == before - burnAmount));
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

    receive() external payable {}
}
